import { useState, useContext } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { ComplaintContext } from "../context/ComplaintContext";
import "../styles/global.css";

function AddComplaint() {
  const { addComplaint } = useContext(ComplaintContext);
  const { state } = useLocation();
  const navigate = useNavigate();

  /* ⭐ fallback if state missing */
  const department = state?.department || "General";

  const fallbackCategories = {
    "Public Works": ["Road damage","Street light","Garbage","Bridge","Footpath"],
    "Water & Sanitation": ["Water leakage","Drainage","Sewage","Low pressure","Water supply"],
    "Health & Safety": ["Hospital issue","Mosquito","Emergency","Food safety"],
    Electricity: ["Power cut","Billing","Loose wire"],
    Transport: ["Traffic","Parking","Accident"],
    General: ["Other"]
  };

  const categories = state?.categories || fallbackCategories[department];

  const [category,setCategory]=useState("");
  const [desc,setDesc]=useState("");
  const [loc,setLoc]=useState("");
  const [emergency,setEmergency]=useState(false);
  const [preview,setPreview]=useState(false);

  const submit=()=>{
    addComplaint({
      department,
      category,
      desc,
      loc,
      emergency,
      status:"Pending"
    });
    navigate("/");
  };

  return (
    <div className="complaint-page animated-bg">
      <div className="complaint-card">
        <button onClick={()=>navigate("/")}>← Back</button>

        <h2>File Complaint — {department}</h2>

        <label>Category</label>
        <select value={category} onChange={(e)=>setCategory(e.target.value)}>
          <option>Select category</option>
          {categories.map((c)=><option key={c}>{c}</option>)}
        </select>

        <label>Description</label>
        <textarea value={desc} onChange={(e)=>setDesc(e.target.value)} />

        <label>Location</label>
        <input value={loc} onChange={(e)=>setLoc(e.target.value)} />

        <div className="toggle">
          <input type="checkbox" checked={emergency} onChange={()=>setEmergency(!emergency)}/>
          Emergency
        </div>

        <button onClick={()=>setPreview(true)}>Preview Complaint</button>

        {preview && (
          <div className="modal">
            <div className="modal-card">
              <h3>Preview</h3>
              <p>{department}</p>
              <p>{category}</p>
              <p>{desc}</p>
              <p>{loc}</p>
              <button onClick={submit}>Submit</button>
              <button onClick={()=>setPreview(false)}>Close</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default AddComplaint;
